<template>
  <article class="xp">
    <div class="xp__body">
      <p class="xp__lead">
        <span class="xp__role">{{ title }}</span>
        <span class="xp__at"> at </span>
        <span class="xp__company">
          <template v-if="companyLinks && companyLinks.length">
            <template v-for="(link, i) in companyLinks" :key="link.url">
              <span v-if="i > 0" class="xp__company-sep"> &amp; </span>
              <a
                class="xp__company-link"
                :href="link.url"
                target="_blank"
                rel="noopener"
              >{{ link.name }}</a>
            </template>
          </template>
          <a
            v-else-if="companyUrl"
            class="xp__company-link"
            :href="companyUrl"
            target="_blank"
            rel="noopener"
          >{{ company }}</a>
          <template v-else>{{ company }}</template>
        </span><span class="xp__period">.</span>
      </p>
      <p
        v-for="(item, i) in assignments"
        :key="i"
        class="xp__detail"
      >
        {{ item }}
      </p>
    </div>
    <time class="xp__when">{{ dateLabel }}</time>
  </article>
</template>

<script>
export default {
  name: 'Experience',
  props: {
    title: String,
    company: String,
    companyUrl: String,
    companyLinks: Array,
    from: String,
    to: String,
    assignments: Array,
    tech_stack: Array
  },
  computed: {
    dateLabel () {
      if (!this.from) return ''

      const fromYear = this.from.split('/').pop()
      if (!this.to) return `${fromYear} -`

      const toYear = this.to.split('/').pop()
      if (fromYear === toYear) return fromYear

      return `${fromYear} - ${toYear}`
    }
  }
}
</script>

