<template>
  <article class="project">
    <div v-if="image" class="project__thumb">
      <img
        class="project__img"
        :src="image"
        :alt="`${title} preview`"
        loading="lazy"
      />
    </div>

    <div class="project__body">
      <header class="project__head">
        <div class="project__titles">
          <h3 class="project__title">
            <router-link
              v-if="showDetailLink"
              class="project__title-link"
              :to="{ name: 'Project', params: { slug } }"
            >
              {{ title }}
            </router-link>
            <template v-else>{{ title }}</template>
          </h3>
          <span v-if="status" class="project__status">{{ status }}</span>
        </div>
        <div class="project__links">
          <a
            v-if="code"
            class="project__link"
            :href="code"
            target="_blank"
            rel="noopener"
          >
            Code
          </a>
          <a
            v-if="website"
            class="project__link"
            :href="website"
            target="_blank"
            rel="noopener"
          >
            Website
          </a>
        </div>
      </header>
      <p class="project__desc">{{ description }}</p>
      <router-link
        v-if="showDetailLink"
        class="project__read"
        :to="{ name: 'Project', params: { slug } }"
      >
        Read the project
      </router-link>
      <ul v-if="tech_stack && tech_stack.length" class="project__stack">
        <li v-for="(tech, i) in tech_stack" :key="i">{{ tech }}</li>
      </ul>
    </div>
  </article>
</template>

<script>
import { projectDetailPagesEnabled } from '@/data/featuredProjects'

export default {
  name: 'Projects',
  props: {
    title: String,
    description: String,
    tech_stack: Array,
    code: String,
    website: String,
    image: String,
    status: String,
    slug: String,
    featured: {
      type: Boolean,
      default: false
    },
    detailEnabled: {
      type: Boolean,
      default: false
    }
  },
  computed: {
    showDetailLink () {
      return (
        projectDetailPagesEnabled &&
        this.detailEnabled &&
        Boolean(this.slug)
      )
    }
  }
}
</script>

